// จำลองค่าจริงของโรงงานให้ dashboard มีชีวิต — เขียนลง virtual PLC ผ่าน writeTag
// stateless: คำนวณจากเวลาล้วน ๆ (restart แล้วเนียนต่อ ไม่กระโดด)
const t = Date.now() / 1000;
const r = (a) => Math.round(a);

// อุณหภูมิ: แกว่งช้า 42-78°C + สั่นเล็กน้อย
writeTag('DEMO01', 'temp', r(60 + 18 * Math.sin(t / 8) + (Math.random() - 0.5) * 3));
// ความดัน: คลื่นคนละจังหวะ 340-460 kPa
writeTag('DEMO01', 'pressure', r(400 + 60 * Math.sin(t / 13 + 1.3) + (Math.random() - 0.5) * 8));
// ระดับถัง: เติม 2 นาที → ระบาย 2 นาที (สามเหลี่ยม 0-100%)
const cyc = (t % 240) / 240;
writeTag('DEMO01', 'level', r(cyc < 0.5 ? cyc * 200 : (1 - cyc) * 200));
// ความเร็วสายพาน: แกว่งรอบ 1350 rpm
writeTag('DEMO01', 'speed', r(1350 + 120 * Math.sin(t / 21)));
// ตัวนับชิ้นงาน: +1 ทุกวินาที (วนที่ 60000 กันเกิน UINT16)
const c = tag('DEMO01', 'counter');
writeTag('DEMO01', 'counter', ((c == null ? 0 : c) + 1) % 60000);
// สูตรผลิต: สลับ 1-5 ทุก 5 นาที
writeTag('DEMO01', 'recipe', Math.floor(t / 300) % 5 + 1);

// จำลองสายการบรรจุ (packaging line) ตามขั้นตอนมาตรฐาน 8 สถานี:
// จัดเรียงขวด → นับ/บรรจุ → ปิดฝา → ตรวจสอบ → ติดฉลาก → บรรจุกล่อง → หีบห่อ → พาเลท
// มี fault สุ่ม: ทุก ~2 นาที บางรอบมี 1 สถานีหยุด ~12 วิ → ทั้งไลน์หยุด (เหมือนไลน์จริงที่ block กัน)
const t = Date.now() / 1000;
const r = Math.round;
const stations = ['unscramble','fill','cap','inspect','label','carton','casepack','palletize'];
const cyc = Math.floor(t / 120);
const h = (cyc * 7919) % 23;                       // hash รอบ — บางรอบไม่มี fault
const faultIdx = h < 8 ? h : -1;
const inFault = faultIdx >= 0 && (t % 120) < 12;
stations.forEach((s, i) => writeTag('DEMO01', 'pk_st_' + s, inFault && i === faultIdx ? 0 : 1));
// ความเร็วไลน์: fault = 0 · ปกติแกว่งรอบ 80 ขวด/นาที
const speed = inFault ? 0 : r(80 + 10 * Math.sin(t / 17) + (Math.random() - 0.5) * 4);
writeTag('DEMO01', 'pk_speed', speed);
// ยอดสะสม: บรรจุเพิ่มตามความเร็ว (สคริปต์รันทุก 1 วิ → speed/60 ขวดต่อรอบ เศษใช้สุ่มปัด)
const filled = tag('DEMO01', 'pk_filled') || 0;
const whole = Math.floor(speed / 60), frac = speed / 60 - whole;
const add = whole + (Math.random() < frac ? 1 : 0);
const nf = (filled + add) % 60000;
writeTag('DEMO01', 'pk_filled', nf);
// คัดออกจากจุดตรวจสอบ ~0.2% (สอดคล้อง accuracy >99.8%)
if (add > 0 && Math.random() < 0.002) {
  writeTag('DEMO01', 'pk_reject', ((tag('DEMO01', 'pk_reject') || 0) + 1) % 60000);
}
// 12 ขวด = 1 กล่อง · 48 กล่อง = 1 พาเลท
writeTag('DEMO01', 'pk_cartons', Math.floor(nf / 12) % 60000);
writeTag('DEMO01', 'pk_pallets', Math.floor(nf / (12 * 48)) % 60000);
// ถังพักขวดเปล่า: ไหลลงเรื่อย ๆ แล้ว refill ทุก ~3 นาที
writeTag('DEMO01', 'pk_hopper', r(100 - (t % 180) / 180 * 70));
